		expect(batch.status).toBe("approved");
		expect(batch.items).toHaveLength(summary.bump + summary.priceOnly);
		expect(batch.runHour).toBe(19);
		expect(batch.runMinute).toBe(0);
		expect(batch.signature).toBe(store.signature());
		expect(store.activeBatch()).toBeNull();
	});

