/**
 * 당근 끌어올리기 규칙.
 *
 * 글마다 타겟 가격과 마감일이 있을 때만 가격을 내린다. 시작가에서 타겟까지 마감일 수로 나눈 하루 몫을
 * 인하 한 번의 폭으로 삼아, 인하가 허락된 날 지금 가격에서 한 몫만 내림 단위로 맞춰 내린다. 못 내린 날은
 * 따라잡지 않고, 마감일에도 타겟을 강제하지 않는다. 끌어올리지 않는 날의 인하는 관심(하트)이 최소 개수 이상이고
 * 지난 인하 때보다 정해진 비율만큼 늘었을 때만 허락한다(반응 없이 가격만 내리면 손해라서).
 * 끌어올리기는 글당 15회·하루 6개 안에서, 쿨타임이 지났고 마지막 노출(끌올, 없으면 게시)이
 * 2일 이상 지난 글을 노출이 오래된 순으로 고른다. 노출 날짜가 같으면 마감이 빠른 글, 그다음 하트가 적은 글이 먼저다.
 */

import { DAILY_BUMP_LIMIT, MAX_BUMPS } from "./cooldown";

/** 판매중 카드 한 장. 조회·채팅은 기록만 하고, 하트 수는 끌올 순서에서 노출 날짜·마감이 같을 때만 쓴다. */
export type Listing = {
	id: string;
	title: string;
	/** 지금 화면의 가격(원) */
	price: number;
	/** 하트 아이콘 옆 숫자 */
	hearts: number;
	views: number;
	chats: number;
	/** `끌올 N일 전`의 N. 끌올 문구가 없으면 null */
	bumpAgoDays: number | null;
	/** `N일 전`(게시 시점)의 N. 끌올한 적 없는 글의 노출 나이. 모르면 null */
	postedAgoDays?: number | null;
	/** 지금까지 끌어올린 횟수. 폰 문구를 못 읽었으면 null */
	bumpCount: number | null;
	/** 마지막 끌올 시각(ISO). 모르면 null */
	bumpedAt: string | null;
	/** 다음 끌올 가능 시각(ISO). 폰이 보여 준 값이 추정보다 우선한다 */
	nextBumpAt: string | null;
	/** 마감에 맞출 가격. 없으면 가격을 내리지 않는다 */
	target: number | null;
	/** 마감일 `YYYY-MM-DD`. 없으면 가격을 내리지 않는다 */
	until: string | null;
	/** 일정을 정한 날의 가격. 직선의 시작점. 없으면 지금 가격·오늘로 본다 */
	startPrice?: number | null;
	/** 일정을 정한 날 `YYYY-MM-DD` */
	startDate?: string | null;
	/** 마지막으로 가격이 내려갔을 때의 관심 수. 아직 내린 적이 없으면 null */
	cutHearts?: number | null;
	/** 실행에 넣는가 */
	included: boolean;
	/** 예약중 글. 끌올·가격 인하에서 빠진다 */
	reserved?: boolean;
};

/** 관리 화면에서 바꾸는 전역 설정. 가격 비율은 글의 타겟·날짜가 정한다. */
export type RuleSet = {
	dailyLimit: number;
	/** 끌어올리지 않는 날 가격을 내리려면 관심이 이 개수 이상이어야 한다 */
	minHearts: number;
	/** 지난 인하 때보다 관심이 이 %만큼 늘어야 다음 인하를 한다 */
	heartGrowthPct: number;
};

export const DEFAULT_RULES: RuleSet = {
	dailyLimit: DAILY_BUMP_LIMIT,
